from pathlib import Path
import hashlib,json,numpy as np,pandas as pd
P=Path('outputs/三模型全月_20261113');O=P/'D0预测弱势与撤单_20261114';ss=pd.read_pickle(P/'D1状态样本全景_20261114/全候选D1分支明细.pkl.gz'); frames=[pd.read_pickle(P/'早期/全部输入.pkl.gz'),pd.read_pickle(P/'全部输入.pkl.gz'),pd.read_pickle(P/'近月/全部输入.pkl.gz')];a=pd.concat(frames,ignore_index=True).drop_duplicates(['d0_date','symbol'],keep='first');a['d0_date']=a.d0_date.astype(str);a['symbol']=a.symbol.astype(str).str.zfill(6)
