for (name,year),g in q.groupby(['实验','year']):
 t=np.load(O/f'{name}_{year}_numpy模型.npz',allow_pickle=False);f=list(t['features']);d=g[['d0','symbol','风险分']].merge(a[['d0_date','symbol']+f],left_on=['d0','symbol'],right_on=['d0_date','symbol'],how='left',validate='one_to_one');x=d[f].apply(pd.to_numeric,errors='coerce').replace([np.inf,-np.inf],np.nan).to_numpy(float);missing=~np.isfinite(x);x=np.where(missing,t['median'],x);x=np.clip((x-t['median'])/t['scale'],-5,5);z=np.column_stack([np.ones(len(x)),x,np.maximum(x-1,0),np.maximum(-x-1,0),missing.astype(float)]);linear=z@t['weights'];pred=1/(1+np.exp(-linear));err=np.max(np.abs(pred-d['风险分'].to_numpy()));out.append({'name':name,'year':int(year),'rows':len(g),'max_score_error':float(err)});assert err<1e-12
