files=[P/'早期/全部输入.pkl.gz',P/'全部输入.pkl.gz',P/'近月/全部输入.pkl.gz',P/'D1状态样本全景_20261114/全候选D1分支明细.pkl.gz',Path('scripts/research_three_f_risk_20261114.py'),Path('scripts/research_three_final_loss_20261114.py'),Path('scripts/verify_three_f_risk_20261114.py')];hashes={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in files};(O/'核验和输入哈希.json').write_text(json.dumps({'portable_model_reload':out,'train_valid_date_assertions':'passed','hashes_sha256':hashes},ensure_ascii=False,indent=2));print('models',len(out),'rows',sum(d['rows'] for d in out),'max_err',max(d['max_score_error'] for d in out),'date checks passed')
